 static T FindVisualDescendant<T>(DependencyObject parent) where T:DependencyObject {return FindVisualDescendant<T>(parent,null);}
 static T FindVisualDescendant<T>(DependencyObject parent,Func<T,bool> accept) where T:DependencyObject {
  for(int i=0;i<System.Windows.Media.VisualTreeHelper.GetChildrenCount(parent);i++){
   var child=System.Windows.Media.VisualTreeHelper.GetChild(parent,i);var match=child as T;if(match!=null&&(accept==null||accept(match)))return match;
   match=FindVisualDescendant<T>(child,accept);if(match!=null)return match;
  }
  return null;
 }
